create table app_user (id bigserial primary key, username varchar(120) not null unique, password_hash varchar(255) not null, role varchar(20) not null, enabled boolean not null default true, created_at timestamptz not null default now());
create table import_batch (id bigserial primary key, filename varchar(255) not null, source_hash char(64) not null, period_end date, contract_no varchar(100), status varchar(30) not null, source_rows integer not null default 0, bill_total numeric(18,2) not null default 0, created_at timestamptz not null default now(), unique(source_hash, period_end, contract_no));
create table connection (id bigserial primary key, mobile_norm varchar(80) not null unique, mobile_display varchar(80) not null, source_kind varchar(40) not null, user_name varchar(255), designation varchar(255), nic varchar(80), location varchar(160), status_raw varchar(60), status_norm varchar(40) not null, package varchar(120), data_plans varchar(255), credit_limit numeric(18,2), company_pay numeric(18,2), connection_type varchar(30) not null default 'Voice', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table connection_source (id bigserial primary key, connection_id bigint references connection(id), mobile_norm varchar(80) not null, source_sheet varchar(120) not null, source_row integer not null, source_json jsonb not null, created_at timestamptz not null default now());
create table billing_batch (id bigserial primary key, import_batch_id bigint not null unique references import_batch(id), period_end date, contract_no varchar(100), created_at timestamptz not null default now());
create table billing_line (id bigserial primary key, billing_batch_id bigint not null references billing_batch(id), mobile_norm varchar(80) not null, mobile_display varchar(80) not null, total_amount_payable numeric(18,2) not null, charges_for_bill_period numeric(18,2), company_pay numeric(18,2), match_status varchar(30) not null, connection_id bigint references connection(id), raw_json jsonb not null, unique(billing_batch_id,mobile_norm));
create table recovery_row (id bigserial primary key, billing_line_id bigint not null unique references billing_line(id), billing_batch_id bigint not null references billing_batch(id), mobile_norm varchar(80) not null, source_bill numeric(18,2) not null, company_pay numeric(18,2) not null default 0, other_charges numeric(18,2) not null default 0, recovery_amount numeric(18,2) not null default 0, company_payable numeric(18,2) not null default 0, recovery_override numeric(18,2), company_payable_override numeric(18,2), match_status varchar(30) not null, approval_status varchar(30) not null default 'DRAFT', review_note varchar(1000), formula_version varchar(30) not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table quality_issue (id bigserial primary key, import_batch_id bigint references import_batch(id), issue_type varchar(80) not null, severity varchar(20) not null, source_sheet varchar(120), source_row integer, mobile_norm varchar(80), message varchar(1000) not null, resolved boolean not null default false, created_at timestamptz not null default now());
create table audit_log (id bigserial primary key, actor varchar(120), action varchar(80) not null, entity_type varchar(80) not null, entity_id bigint, details jsonb not null, created_at timestamptz not null default now());
create index idx_billing_line_match on billing_line(billing_batch_id, match_status);
create index idx_recovery_review on recovery_row(approval_status);
create index idx_connection_location on connection(location);
